    assert_close(&landmass.quality, &expected_landmass, "landmass_quality case0_region");
    assert_eq!(landmass.count, expected_landmass_count, "landmass_count case0_region");

    let coast_sdf = cartalith_civ::build_coast_sdf(&ws.field, 14, 11, ws.sea_level);
    assert_close(&coast_sdf, &expected_coast_sdf, "coast_sdf case0_region");
